// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(actor != c.owner());
        vm.startPrank(actor);
        bool ok = true;
        try c.transferOwnership(newOwner) { }
        catch { ok = false; }
        vm.stopPrank();
        assertTrue(ok == false || c.owner() == c.owner());
        assertTrue(ok == false);
    }
}
